def solve_coin_flips(n):
    N = 2 * n + 1
    flips = []
    # P_k = (k(k+1)/2 - 1) mod N for k=1 to N
    for k in range(1, N + 1):
        # Calculate k*(k+1)/2
        sum_k = k * (k + 1) // 2

        # P_k = sum_k - 1
        P_k = (sum_k - 1) % N
        flips.append(P_k)

    # Count occurrences of each coin index
    counts = {}
    for p in flips:
        counts[p] = counts.get(p, 0) + 1

    # Count how many coins were flipped an odd number of times
    odd_flip_count = 0
    for count in counts.values():
        if count % 2 != 0:
            odd_flip_count += 1

    return odd_flip_count

# Test cases:
test_n = [1, 2, 3, 4, 5, 6, 7]
results = {}
for n in test_n:
    results[n] = solve_coin_flips(n)

